"""Offline exact-resource deletion contract; provider and DB are synthetic."""
from contextlib import contextmanager
from copy import deepcopy
import json
import sqlite3

import pytest

from cleanup_executor import Executor, Refused, digest


class Local:
    def __init__(self, path, targets, canonical):
        self.path, self.canonical = path, canonical
        self.blockers = {t['id']: [] for t in targets}
        self.revision = 1
        with self.connect() as db:
            db.execute('CREATE TABLE accounts(handle TEXT PRIMARY KEY, credential TEXT)')
            db.execute("INSERT INTO accounts VALUES ('saved-account','credential-secret-reference')")
    @contextmanager
    def connect(self):
        db = sqlite3.connect(self.path); db.row_factory = sqlite3.Row
        try:
            yield db
            db.commit()
        except BaseException:
            db.rollback(); raise
        finally: db.close()
    def snapshot(self, db):
        return dict(canonical=deepcopy(self.canonical), local_digest=digest({'revision':self.revision}),
                    target_blockers=deepcopy(self.blockers))


class Provider:
    def __init__(self, targets, canonical):
        self.profiles = {r['id']:deepcopy(r) for r in targets+canonical}
        self.auth = {c:dict(id=c,profile_name=t['name'],generation='a'*64,terminal=True,
                          active_writer=False,credential_ids=['credential00001'],backing_references=0)
                     for t in targets for c in t['connection_ids']}
        for p in self.profiles.values(): p.pop('connection_ids',None)
        self.creds = {'credential00001':dict(id='credential00001',fingerprint='c'*64)}
        self.calls=[]; self.browsers=[]; self.fail=None; self.on_get=None; self.on_delete=None
    def profile(self, identity):
        if self.on_get:
            f,self.on_get=self.on_get,None; f()
        return deepcopy(self.profiles.get(identity) or next((p for p in self.profiles.values() if p['name']==identity),None))
    def connections(self, name): return deepcopy([r for r in self.auth.values() if r['profile_name']==name])
    def connection(self, identity): return deepcopy(self.auth.get(identity))
    def credential(self, identity): return deepcopy(self.creds.get(identity))
    def active_browsers(self): return deepcopy(self.browsers)
    def inventory(self): return deepcopy(list(self.profiles.values()))
    def _delete(self,kind,identity,collection):
        self.calls.append((kind,identity))
        if self.on_delete:
            f,self.on_delete=self.on_delete,None;f()
        if self.fail=='present': raise TimeoutError('SECRET_PROVIDER_PAYLOAD')
        collection.pop(identity,None)
        if self.fail=='absent': raise TimeoutError('SECRET_PROVIDER_PAYLOAD')
        if self.fail=='crash': raise KeyboardInterrupt()
    def delete_connection(self,identity): self._delete('connection',identity,self.auth)
    def delete_profile(self,identity): self._delete('profile',identity,self.profiles)


class Maintenance:
    def __init__(self): self.live=True;self.boot='gateway-1234'
    def check(self):
        if not self.live: raise RuntimeError('PRIVATE_LOCK_DETAIL')
        return self.boot


