def execute(ex,m): return ex.execute(m,approved_sha256=digest(m))


def test_complete_exact32_and_preserve_accounts(prepared):
    ex,m,local,p,gate=prepared
    out=execute(ex,m)
    assert out==dict(status='complete',manifest_sha256=digest(m),gateway_boot='gateway-1234',profiles_deleted=32,connections_deleted=2,unknown=0,remaining_profiles=4,reason=None)
    with local.connect() as db:
        assert tuple(db.execute('SELECT * FROM accounts').fetchone())==('saved-account','credential-secret-reference')
    assert p.creds=={'credential00001':dict(id='credential00001',fingerprint='c'*64)}
    calls=list(p.calls); assert execute(ex,m)['status']=='complete' and p.calls==calls


@pytest.mark.parametrize('change', ['approval','scope','canonical','generation','name','owner','active','pending','unknown','reference','vault_reference','credential','new_connection','incomplete','lock','revision'])
def test_refuses_changed_authority_before_mutation(prepared,change):
    ex,m,local,p,gate=prepared;t=m['scope']['delete_profiles'][0];c=t['connection_ids'][0]
    approved=digest(m)
    if change=='approval': approved='0'*64
    if change=='scope': m['scope']['delete_profiles'][0]['id']='forged-profile'
    if change=='canonical': local.canonical[0]['id']=t['id']
    if change=='generation': p.auth[c]['generation']='b'*64
    if change=='name': p.profiles[t['id']]['name']='new-name'
    if change=='owner': p.profiles[t['id']]['owner']='UOTHER'
    if change=='active': p.browsers.append(dict(id='activebrowser'))
    if change in ('pending','unknown','reference'): local.blockers[t['id']]=[change]
    if change=='vault_reference': p.auth[c]['backing_references']=1
    if change=='credential': p.creds['credential00001']['fingerprint']='f'*64
    if change=='new_connection': p.auth['extra']=dict(p.auth[c],id='extra')
    if change=='incomplete': p.connections=lambda name: None
    if change=='lock': gate.live=False
    if change=='revision': local.revision+=1
    out=ex.execute(m,approved_sha256=approved)
    assert out['status']=='refused' and p.calls==[]
    assert 'PRIVATE' not in json.dumps(out)


